def isUgly(n: int) -> bool:
    # Ugly numbers must be positive
    if n <= 0:
        return False

    # Repeatedly divide out allowed prime factors
    for factor in [2, 3, 5]:
        while n % factor == 0:
            n //= factor

    # In the end, if we have reduced n to 1, it's ugly
    return n == 1
